import{WORLD,TABITHA}from'./scenario.js';import{createState,record,tabithaReachedBanner,bannerAction,inspectBannerClue,tabithaReachedSide,sideAction,inspectPlaque,beginEnding,finishRun}from'./model.js';
export function createWorldRuntime({canvas,hudTime,promptEl,noticeEl,situationEl}){const ctx=canvas.getContext('2d');let state=createState(),keys=new Set(),paused=false,inputContext='world',current=0,sceneHandler=()=>{},endHandler=()=>{},noticeTimer=null,worldSeconds=0;
function reset(){state=createState();state.runId=globalThis.crypto?.randomUUID?.()||`run-${Date.now()}`;keys=new Set();paused=false;inputContext='world';current=0;worldSeconds=0;showNotice('Friday, 19:03. You and Tabitha have just reached the community hall.',4200);setSituation('Tabitha has stopped before going inside. Something on the frontage has caught her eye.');record(state,'run_started');}
function showNotice(text,ms=3200){noticeEl.textContent=text;noticeEl.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>noticeEl.classList.remove('visible'),ms);}function setSituation(text){situationEl.textContent=text||'';}function setKey(k,d){if(inputContext!=='world')return;d?keys.add(k):keys.delete(k);}function clearKeys(){keys.clear();}function setInputContext(v){inputContext=v;if(v!=='world')clearKeys();}function setPaused(v){paused=v;}function setSceneHandler(fn){sceneHandler=fn;}function setEndHandler(fn){endHandler=fn;}
function collides(x,y){const r=14;if(x<36||y<36||x>WORLD.width-36||y>WORLD.height-36)return true;return WORLD.obstacles.some(o=>x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h);}function movePlayer(dt){if(paused||inputContext!=='world'||state.ended)return;let dx=0,dy=0;if(keys.has('w')||keys.has('arrowup'))dy--;if(keys.has('s')||keys.has('arrowdown'))dy++;if(keys.has('a')||keys.has('arrowleft'))dx--;if(keys.has('d')||keys.has('arrowright'))dx++;if(!dx&&!dy)return;const l=Math.hypot(dx,dy);dx/=l;dy/=l;const nx=state.player.x+dx*190*dt,ny=state.player.y+dy*190*dt;if(!collides(nx,state.player.y))state.player.x=nx;if(!collides(state.player.x,ny))state.player.y=ny;}
function moveTabitha(dt){const t=state.tabitha,tar=t.target;if(!tar)return;const dx=tar.x-t.x,dy=tar.y-t.y,d=Math.hypot(dx,dy);if(d>2){t.x+=dx/d*Math.min(d,105*dt);t.y+=dy/d*Math.min(d,105*dt);}if(d<=8&&state.activity.stage==='approach_banner'){tabithaReachedBanner(state);afterStateChange();}if(d<=8&&state.activity.stage==='moving_side'){tabithaReachedSide(state);afterStateChange();}if(d<=8&&state.activity.pendingEnding){const ending=state.activity.pendingEnding;finishRun(state,ending);endHandler();}}
function near(p,r=120){return Math.hypot(state.player.x-p.x,state.player.y-p.y)<=r;}function nearTabitha(r=140){return Math.hypot(state.player.x-state.tabitha.x,state.player.y-state.tabitha.y)<=r;}
function candidates(){if(state.ended)return[];const out=[],st=state.activity.stage;if(['banner','banner_clue'].includes(st)&&near(WORLD.points.bannerFront,135)){if(st==='banner'){out.push({id:'hold_corner',label:'Hold the loose corner'},{id:'phone_torch',label:'Use your phone torch'},{id:'let_tabitha_try',label:'Let Tabitha try it'},{id:'warn_off',label:'Tell her not to peel it'});}else out.push({id:'read_letters',label:'Read the exposed letters'},{id:'check_date',label:'Check the stone below'},{id:'challenge_institute',label:'Question Tabitha’s guess'});}if(['side','side_search'].includes(st)&&near(WORLD.points.sideSeam,145)){out.push({id:'inspect_seam',label:'Inspect the brick seam'},{id:'check_rust',label:'Check the rust mark'},{id:'ask_what_she_sees',label:'Ask what Tabitha sees'},{id:'call_it_repair',label:'Say it could just be a repair'});if(nearTabitha(150))out.push({id:'focused_exchange',label:'Talk while you look'});}if(st==='door_confirmed'&&near(WORLD.points.sidePlaque,120))out.push({id:'inspect_plaque',label:'Check the old plaque'});if(st==='resolution'){if(near(WORLD.points.entrance,125))out.push({id:'inside_together',label:'Go inside with Tabitha'});if(near(WORLD.points.lowWall,150))out.push({id:'keep_looking',label:'Keep circling the building'});}if(near(WORLD.points.entrance,100)&&st!=='resolution')out.push({id:'inside_early',label:'Go inside instead'});if(near(WORLD.points.streetExit,100))out.push({id:'leave',label:'Head off'});const seen=new Set();return out.filter(x=>!seen.has(x.id)&&seen.add(x.id));}
function cycleTarget(){const a=candidates();if(!a.length)return;current=(current+1)%a.length;renderPrompt();}
function interact(){const a=candidates();if(!a.length)return;const it=a[Math.min(current,a.length-1)];if(['hold_corner','phone_torch','let_tabitha_try','warn_off'].includes(it.id))bannerAction(state,it.id);else if(['read_letters','check_date','challenge_institute'].includes(it.id))inspectBannerClue(state,it.id);else if(['inspect_seam','check_rust','ask_what_she_sees','call_it_repair'].includes(it.id))sideAction(state,it.id);else if(it.id==='focused_exchange'){sceneHandler();return;}else if(it.id==='inspect_plaque')inspectPlaque(state);else if(it.id==='inside_together'){beginEnding(state,'inside_together');afterStateChange();return;}else if(it.id==='keep_looking'){beginEnding(state,'keep_looking');afterStateChange();return;}else if(it.id==='inside_early'){finishRun(state,'inside_early');endHandler();return;}else if(it.id==='leave'){finishRun(state,'leave');endHandler();return;}afterStateChange();}
function afterStateChange(){const last=state.visibleChanges.at(-1);if(last)showNotice(last.detail,3600);const st=state.activity.stage;if(st==='banner')setSituation('Tabitha is trying to work out what the new banner is covering.');else if(st==='banner_clue')setSituation('You have a partial clue from the old stonework.');else if(st==='moving_side')setSituation('Tabitha is heading round the side to test her guess. Following is optional.');else if(['side','side_search'].includes(st))setSituation('The side wall may still show where the old entrance used to be.');else if(st==='door_confirmed')setSituation('You have confirmed an old doorway. Tabitha is looking for whatever labelled the room.');else if(st==='resolution'&&state.activity.pendingEnding==='keep_looking')setSituation('Tabitha is following the investigation around toward the back wall.');else if(st==='resolution'&&state.activity.pendingEnding==='inside_together')setSituation('You and Tabitha are heading back to the entrance.');else if(st==='resolution')setSituation('The old READING ROOM entrance is visible in fragments. You can stop here or keep going.');renderPrompt();}
function renderPrompt(){const a=candidates();if(current>=a.length)current=0;promptEl.textContent=a.length?`E — ${a[current].label}`:'';}function tick(dt){worldSeconds+=dt;movePlayer(dt);moveTabitha(dt);renderPrompt();hudTime.textContent=state.fictionalTime;}
function draw(){ctx.clearRect(0,0,900,520);ctx.fillStyle='#abb6a5';ctx.fillRect(0,0,900,520);ctx.fillStyle='#d8c8ac';ctx.fillRect(250,70,430,270);ctx.strokeStyle='#776c5f';ctx.lineWidth=3;ctx.strokeRect(250,70,430,270);ctx.fillStyle='#8f765e';ctx.fillRect(300,320,72,20);ctx.fillStyle='#403b35';ctx.font='12px system-ui';ctx.fillText('ENTRANCE',302,315);ctx.fillStyle='#756a5c';ctx.font='bold 22px Georgia';ctx.fillText('... INSTITUTE 1908',360,302);ctx.fillStyle='#4d7d7c';ctx.fillRect(338,268,264,58);ctx.fillStyle='#f4efe4';ctx.font='bold 16px system-ui';ctx.fillText('COMMUNITY RESILIENCE HUB',356,302);if(state.banner.heldByPlayer||state.banner.torchUsed||state.banner.touchedByTabitha){ctx.fillStyle='#d8c8ac';ctx.fillRect(566,268,36,58);ctx.fillStyle='#756a5c';ctx.font='bold 16px Georgia';ctx.fillText(state.banner.visibleText||'TUTE',540,296);}if(state.banner.dateVisible){ctx.fillStyle='#756a5c';ctx.font='bold 12px Georgia';ctx.fillText('1908',548,320);}ctx.strokeStyle=state.facts.doorConfirmed?'#66594d':'#8d7f70';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(680,155);ctx.lineTo(680,322);ctx.stroke();if(state.facts.playerFoundHinge||state.facts.doorConfirmed){ctx.fillStyle='#7c4e36';ctx.fillRect(681,248,10,22);ctx.fillRect(684,252,2,2);ctx.fillRect(684,264,2,2);}if(state.facts.plaqueSeen){ctx.fillStyle='#6b655d';ctx.fillRect(676,154,68,24);ctx.fillStyle='#eee6d8';ctx.font='10px serif';ctx.fillText('READING ROOM',681,170);}ctx.fillStyle='#7d6c59';ctx.fillRect(748,385,86,20);ctx.beginPath();ctx.arc(state.tabitha.x,state.tabitha.y,18,0,Math.PI*2);ctx.fillStyle=TABITHA.color;ctx.fill();ctx.lineWidth=3;ctx.strokeStyle='#fff8ed';ctx.stroke();ctx.fillStyle='#292622';ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText('TAB',state.tabitha.x,state.tabitha.y+4);if(state.tabitha.speech&&worldSeconds<state.tabitha.speechUntil)drawSpeech(state.tabitha.x,state.tabitha.y-30,state.tabitha.speech);ctx.beginPath();ctx.arc(state.player.x,state.player.y,15,0,Math.PI*2);ctx.fillStyle='#272522';ctx.fill();ctx.lineWidth=4;ctx.strokeStyle='#fff';ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 10px system-ui';ctx.fillText('YOU',state.player.x,state.player.y+4);ctx.textAlign='start';}
function drawSpeech(x,y,text){ctx.font='12px system-ui';const w=Math.min(270,ctx.measureText(text).width+24),left=Math.max(12,x-w/2);ctx.fillStyle='#151613e8';ctx.fillRect(left,y-28,w,30);ctx.fillStyle='#f2ede4';ctx.textAlign='center';const shown=text.length>48?`${text.slice(0,47)}…`:text;ctx.fillText(shown,left+w/2,y-9);ctx.textAlign='start';}
reset();return{get state(){return state},tick,draw,interact,cycleTarget,setKey,clearKeys,setInputContext,setPaused,setSceneHandler,setEndHandler,showNotice,afterStateChange,reset};}
